pub trait Metrics: Send + Sync { fn record(&self, ev: Event); }

#[derive(Default)]
pub struct NoMetrics;                     // zero-sized, stateless
impl Metrics for NoMetrics { fn record(&self, _ev: Event) {} }

fn metrics(enabled: bool) -> Box<dyn Metrics> {
    if enabled { Box::new(RealMetrics::new()) } else { Box::new(NoMetrics) }
}
